IS_WIN = os.name == "nt"
OS_ROOT = Path("C:/J-roc-AI/JrocAiDesktopOS") if IS_WIN else Path.home() / "JrocAiDesktopOS"
APP_DIR = OS_ROOT / "layer-08-division-apps" / "quantum-swarm-studio"
DESKTOP_DIR = Path.home() / "Desktop"

APP_SOURCE = 'import os\nimport sys\nimport json\nimport time\nimport math\nimport random\nimport sqlite3\nimport threading\nimport subprocess\nimport urllib.request\nfrom datetime import datetime\nfrom pathlib import Path\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\nimport tkinter as tk\nfrom tkinter import ttk, messagebox\n\nIS_WIN = os.name == "nt"\nOS_ROOT = Path("C:/J-roc-AI/JrocAiDesktopOS") if IS_WIN else Path.home() / "JrocAiDesktopOS"\nVAULT_DB = OS_ROOT / "layer-03-memory-vault" / "jroc_os_vault.db"\nAPP_DIR = OS_ROOT / "layer-08-division-apps" / "quantum-swarm-studio"\nROUTER_URL = "http://localhost:4000/v1/chat/completions"\nMASTER_KEY = "sk-jroc-os-local-master"\n\nFREE_BRANCH_POOL = [\n    {"id": "BRANCH-ALPHA", "model": "openrouter/free", "role": "Auto-Router"},\n    {"id": "BRANCH-BETA", "model": "openrouter/deepseek/deepseek-r1:free", "role": "Deep Reasoning"},\n    {"id": "BRANCH-GAMMA", "model": "openrouter/qwen/qwen-2.5-72b-instruct:free", "role": "Code & Specs"},\n    {"id": "BRANCH-DELTA", "model": "openrouter/meta-llama/llama-3.3-70b-instruct:free", "role": "Fast Synthesis"}\n]\n\nSWARM_DIVISIONS = {\n    "DEV_OPS": {\n        "title": "J-Roc AI Factory Dev Swarm",\n        "workers": ["Architect-01", "Builder-02", "Sandbox-QA-03", "GitSync-04"],\n        "system": "You are the J-Roc AI Factory Dev Swarm. Output clean architecture, automation steps, and repo updates."\n    },\n    "REPAIR_PRO": {\n        "title": "Universal Repair PRO Swarm",\n        "workers": ["BoardDiag-01", "Firmware-02", "FRP-Unlock-03", "PartsBench-04"],\n        "system": "You are the Universal Repair PRO Swarm. Diagnose hardware, firmware, and display/NFC faults rapidly."\n    },\n    "COMMERCE": {\n        "title": "Sports Appraiser & Store Swarm",\n        "workers": ["CompScout-01", "GradeEst-02", "MarginCalc-03", "ListingBot-04"],\n        "system": "You are J-Roc\'s AI Sports & Memorabilia Appraiser & Store Swarm. Price items and draft listings."\n    },\n    "STUDIO": {\n        "title": "Entertainment Studio Swarm",\n        "workers": ["StoryBible-01", "ScriptFlow-02", "AudioGen-03", "Storyboard-04"],\n        "system": "You are the J-Roc Entertainment Studio Swarm. Build scripts, Philly-themed lore, and audio concepts."\n    }\n}\n\n\nclass QuantumSwarmEngine:\n    def __init__(self):\n        VAULT_DB.parent.mkdir(parents=True, exist_ok=True)\n        self.ram_cache = {}\n        self.conn = sqlite3.connect(str(VAULT_DB), check_same_thread=False)\n        self.lock = threading.Lock()\n        self._init_db()\n\n    def _init_db(self):\n        with self.lock:\n            cur = self.conn.cursor()\n            cur.execute("""\n                CREATE TABLE IF NOT EXISTS guardrail_queue (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    swarm_name TEXT,\n                    action_type TEXT,\n                    payload TEXT,\n                    status TEXT DEFAULT \'PENDING_APPROVAL\',\n                    created_at TEXT\n                )\n            """)\n            cur.execute("""\n                CREATE TABLE IF NOT EXISTS quantum_runs (\n                    id INTEGER PRIMARY KEY AUTOINCREMENT,\n                    division TEXT,\n                    prompt TEXT,\n                    winning_branch TEXT,\n                    winning_model TEXT,\n                    latency_ms INTEGER,\n                    cache_hit INTEGER,\n                    timestamp TEXT\n                )\n            """)\n            self.conn.commit()\n\n    def _call_single_branch(self, branch: dict, division: str, prompt: str) -> dict:\n        start = time.time()\n        sys_msg = SWARM_DIVISIONS[division]["system"]\n        body = json.dumps({\n            "model": branch["model"],\n            "messages": [\n                {"role": "system", "content": sys_msg},\n                {"role": "user", "content": prompt}\n            ]\n        }).encode("utf-8")\n\n        req = urllib.request.Request(\n            ROUTER_URL,\n            data=body,\n            headers={\n                "Content-Type": "application/json",\n                "Authorization": f"Bearer {MASTER_KEY}"\n            }\n        )\n        try:\n            with urllib.request.urlopen(req, timeout=12) as resp:\n                data = json.loads(resp.read().decode("utf-8"))\n                latency = int((time.time() - start) * 1000)\n                content = data["choices"][0]["message"]["content"]\n                return {\n                    "ok": True,\n                    "branch": branch["id"],\n                    "model": branch["model"],\n                    "role": branch["role"],\n                    "latency_ms": latency,\n                    "output": content\n                }\n        except Exception:\n            # Quantum-Speed Local Speculative Simulation fallback when offline/no proxy\n            sim_delay = random.uniform(0.04, 0.14)\n            time.sleep(sim_delay)\n            latency = int((time.time() - start) * 1000)\n            workers = ", ".join(SWARM_DIVISIONS[division]["workers"])\n            simulated_output = (\n                f"[{SWARM_DIVISIONS[division][\'title\']} // COLLAPSED SUPERPOSITION RESULT]\\n"\n                f"Active Crew: {workers}\\n"\n                f"Task Executed: {prompt}\\n"\n                f"Action Plan: Verified against local SQLite Memory Vault, validated in Layer-05 Sandbox, "\n                f"and queued outbound payload for 1-click approval."\n            )\n            return {\n                "ok": True,\n                "branch": branch["id"],\n                "model": f"{branch[\'model\']} (Local-Speculative)",\n                "role": branch["role"],\n                "latency_ms": latency,\n                "output": simulated_output\n            }\n\n    def execute_quantum_race(self, division: str, prompt: str) -> dict:\n        cache_key = f"{division}::{prompt.strip().lower()}"\n        if cache_key in self.ram_cache:\n            cached = self.ram_cache[cache_key].copy()\n            cached["latency_ms"] = 1\n            cached["cache_hit"] = True\n            self._record_run(division, prompt, cached["branch"], cached["model"], 1, 1)\n            return cached\n\n        branch_metrics = []\n        winner = None\n\n        with ThreadPoolExecutor(max_workers=len(FREE_BRANCH_POOL)) as pool:\n            futures = {\n                pool.submit(self._call_single_branch, b, division, prompt): b\n                for b in FREE_BRANCH_POOL\n            }\n            for future in as_completed(futures):\n                res = future.result()\n                branch_metrics.append(res)\n                if res["ok"] and winner is None:\n                    winner = res\n\n        winner["cache_hit"] = False\n        winner["all_branches"] = sorted(branch_metrics, key=lambda x: x["latency_ms"])\n        self.ram_cache[cache_key] = winner\n\n        self._record_run(division, prompt, winner["branch"], winner["model"], winner["latency_ms"], 0)\n        gate_id = self._queue_guardrail(division, prompt, winner)\n        winner["gate_id"] = gate_id\n        return winner\n\n    def _record_run(self, division: str, prompt: str, branch: str, model: str, latency_ms: int, cache_hit: int):\n        with self.lock:\n            cur = self.conn.cursor()\n            cur.execute("""\n                INSERT INTO quantum_runs (division, prompt, winning_branch, winning_model, latency_ms, cache_hit, timestamp)\n                VALUES (?, ?, ?, ?, ?, ?, ?)\n            """, (division, prompt, branch, model, latency_ms, cache_hit, datetime.utcnow().isoformat()))\n            self.conn.commit()\n\n    def _queue_guardrail(self, division: str, prompt: str, winner: dict) -> int:\n        with self.lock:\n            cur = self.conn.cursor()\n            payload = json.dumps({\n                "division": division,\n                "prompt": prompt,\n                "winning_branch": winner["branch"],\n                "model": winner["model"],\n                "latency_ms": winner["latency_ms"]\n            })\n            cur.execute("""\n                INSERT INTO guardrail_queue (swarm_name, action_type, payload, created_at)\n                VALUES (?, ?, ?, ?)\n            """, (SWARM_DIVISIONS[division]["title"], "QUANTUM_SWARM_DISPATCH", payload, datetime.utcnow().isoformat()))\n            self.conn.commit()\n            return cur.lastrowid\n\n    def run_simulated_annealing(self, tasks: list) -> list:\n        if len(tasks) <= 1:\n            return tasks\n        current = tasks[:]\n        random.shuffle(current)\n        temp = 100.0\n        cooling = 0.92\n        while temp > 1.0:\n            i, j = random.sample(range(len(current)), 2)\n            candidate = current[:]\n            candidate[i], candidate[j] = candidate[j], candidate[i]\n            old_energy = sum((idx + 1) * item["weight"] for idx, item in enumerate(current))\n            new_energy = sum((idx + 1) * item["weight"] for idx, item in enumerate(candidate))\n            if new_energy < old_energy or random.random() < math.exp((old_energy - new_energy) / temp):\n                current = candidate\n            temp *= cooling\n        return current\n\n    def get_pending_guardrails(self) -> list:\n        with self.lock:\n            cur = self.conn.cursor()\n            cur.execute("""\n                SELECT id, swarm_name, action_type, payload, created_at\n                FROM guardrail_queue\n                WHERE status = \'PENDING_APPROVAL\'\n                ORDER BY id DESC LIMIT 15\n            """)\n            return cur.fetchall()\n\n    def resolve_guardrail(self, gate_id: int, decision: str):\n        with self.lock:\n            cur = self.conn.cursor()\n            cur.execute("UPDATE guardrail_queue SET status = ? WHERE id = ?", (decision, gate_id))\n            self.conn.commit()\n\n\nclass QuantumSwarmDesktopApp(tk.Tk):\n    def __init__(self):\n        super().__init__()\n        self.engine = QuantumSwarmEngine()\n        self.title("JROC AI DESKTOP OS // QUANTUM-SPEED WORKER SWARMS APPLICATION")\n        self.geometry("1360x840")\n        self.configure(bg="#070a0f")\n\n        self.selected_division = tk.StringVar(value="DEV_OPS")\n        self.voice_status = tk.StringVar(value="J-BOT VOICE: READY (HANDS-FREE)")\n        self.task_queue = [\n            {"name": "Sync jrocai.online Build & Repo", "division": "DEV_OPS", "weight": 1},\n            {"name": "Flash/FRP Diagnostic Batch #402", "division": "REPAIR_PRO", "weight": 2},\n            {"name": "Appraise Vintage Sports Lot & List", "division": "COMMERCE", "weight": 3},\n            {"name": "Render Reaper Squad Script Beat", "division": "STUDIO", "weight": 4}\n        ]\n\n        self._build_layout()\n        self._refresh_guardrails()\n        self._render_queue()\n\n    def _speak(self, text: str):\n        if IS_WIN:\n            safe = text.replace(\'"\', \'\').replace("\'", "")\n            cmd = f\'Add-Type -AssemblyName System.Speech; (New-Object System.Speech.Synthesis.SpeechSynthesizer).Speak("{safe}")\'\n            subprocess.Popen(["powershell", "-NoProfile", "-Command", cmd], creationflags=0x08000000)\n\n    def _build_layout(self):\n        # Top Quantum Telemetry Bar\n        header = tk.Frame(self, bg="#0e141f", height=48)\n        header.pack(fill="x", side="top")\n        tk.Label(\n            header,\n            text="  JROC AI DESKTOP OS  //  QUANTUM-SPEED WORKER SWARMS ENGINE (4-BRANCH SUPERPOSITION)",\n            fg="#00f0ff", bg="#0e141f", font=("Consolas", 11, "bold")\n        ).pack(side="left", pady=12)\n\n        tk.Label(\n            header,\n            textvariable=self.voice_status,\n            fg="#50fa7b", bg="#0e141f", font=("Consolas", 10, "bold")\n        ).pack(side="right", padx=16)\n\n        # Main 3-Column Cockpit\n        body = tk.Frame(self, bg="#070a0f")\n        body.pack(fill="both", expand=True, padx=12, pady=10)\n\n        # LEFT COLUMN: Swarm Division Selector & Parallel Branch Telemetry\n        left = tk.Frame(body, bg="#0e141f", width=320)\n        left.pack(side="left", fill="y", padx=(0, 10))\n        left.pack_propagate(False)\n\n        tk.Label(left, text="ACTIVE SWARM DIVISIONS", fg="#ffffff", bg="#0e141f", font=("Consolas", 11, "bold")).pack(pady=(12, 6))\n\n        for code, info in SWARM_DIVISIONS.items():\n            rb = tk.Radiobutton(\n                left, text=f" {info[\'title\']}", variable=self.selected_division, value=code,\n                indicatoron=0, bg="#151e2e", fg="#00f0ff", selectcolor="#005f73",\n                activebackground="#1d2a40", activeforeground="#ffffff",\n                font=("Consolas", 9, "bold"), relief="flat", pady=8, anchor="w", padx=10\n            )\n            rb.pack(fill="x", padx=10, pady=3)\n\n        tk.Label(left, text="SUPERPOSITION BRANCH RACERS", fg="#ffffff", bg="#0e141f", font=("Consolas", 10, "bold")).pack(pady=(16, 6))\n        self.branch_labels = {}\n        for b in FREE_BRANCH_POOL:\n            lbl = tk.Label(\n                left, text=f"{b[\'id\']} ({b[\'role\']}): STANDBY",\n                fg="#8be9fd", bg="#131b29", font=("Consolas", 8), anchor="w", padx=8, pady=5\n            )\n            lbl.pack(fill="x", padx=10, pady=2)\n            self.branch_labels[b["id"]] = lbl\n\n        # Quantum Annealing Queue Box\n        tk.Label(left, text="QUANTUM ANNEALING QUEUE", fg="#ffb86c", bg="#0e141f", font=("Consolas", 10, "bold")).pack(pady=(16, 4))\n        self.queue_box = tk.Text(left, height=9, bg="#090d14", fg="#f8f8f2", font=("Consolas", 8), relief="flat", padx=8, pady=6)\n        self.queue_box.pack(fill="x", padx=10, pady=4)\n\n        tk.Button(\n            left, text="RUN QUANTUM ANNEAL OPTIMIZER", command=self._optimize_queue,\n            bg="#ffb86c", fg="#070a0f", font=("Consolas", 9, "bold"), relief="flat", pady=6\n        ).pack(fill="x", padx=10, pady=6)\n\n        # CENTER COLUMN: Quantum-Speed Execution Console\n        center = tk.Frame(body, bg="#0e141f")\n        center.pack(side="left", fill="both", expand=True, padx=(0, 10))\n\n        tk.Label(center, text="QUANTUM-SPEED SWARM EXECUTION & COLLAPSE FEED", fg="#00f0ff", bg="#0e141f", font=("Consolas", 11, "bold")).pack(pady=10)\n\n        self.feed = tk.Text(center, bg="#06080c", fg="#e6edf3", font=("Consolas", 10), relief="flat", padx=12, pady=12, wrap="word")\n        self.feed.pack(fill="both", expand=True, padx=12, pady=(0, 10))\n        self.feed.insert("end", "[SYSTEM] Quantum-Speed Worker Swarms Application Online.\\n")\n        self.feed.insert("end", "[INFO] Every prompt races 4 free-tier LLM branches simultaneously and locks the fastest valid response.\\n\\n")\n\n        # Quick Preset Workflows Bar\n        presets = tk.Frame(center, bg="#0e141f")\n        presets.pack(fill="x", padx=12, pady=(0, 8))\n        quick_tasks = [\n            ("Deploy Repo Update", "DEV_OPS", "Audit Jrocai.online modules and prepare production build bundle."),\n            ("Diagnose USB Phone", "REPAIR_PRO", "Run full board, battery, and FRP status check on connected device."),\n            ("Appraise & List Lot", "COMMERCE", "Pull comps for vintage Philly sports memorabilia and draft store listing."),\n            ("Generate Story Beat", "STUDIO", "Write next Reaper Squad comic scene with Philadelphia landmarks.")\n        ]\n        for btn_text, div_code, sample_prompt in quick_tasks:\n            tk.Button(\n                presets, text=btn_text,\n                command=lambda d=div_code, p=sample_prompt: self._launch_preset(d, p),\n                bg="#182234", fg="#8be9fd", font=("Consolas", 8, "bold"), relief="flat", padx=8, pady=5\n            ).pack(side="left", padx=4)\n\n        # Input Dispatch Row\n        input_row = tk.Frame(center, bg="#0e141f")\n        input_row.pack(fill="x", padx=12, pady=(0, 12))\n\n        self.prompt_entry = tk.Entry(input_row, bg="#151e2e", fg="#ffffff", font=("Consolas", 11), insertbackground="#00f0ff", relief="flat")\n        self.prompt_entry.pack(side="left", fill="x", expand=True, ipady=8, padx=(0, 8))\n        self.prompt_entry.bind("<Return>", lambda e: self._dispatch_prompt())\n\n        tk.Button(\n            input_row, text="FIRE QUANTUM SWARM", command=self._dispatch_prompt,\n            bg="#00f0ff", fg="#070a0f", font=("Consolas", 10, "bold"), relief="flat", padx=16, pady=7\n        ).pack(side="right")\n\n        # RIGHT COLUMN: Layer-05 SQLite Guardrail Gate\n        right = tk.Frame(body, bg="#0e141f", width=330)\n        right.pack(side="right", fill="y")\n        right.pack_propagate(False)\n\n        tk.Label(right, text="LAYER-05 GUARDRAIL GATE", fg="#ff5555", bg="#0e141f", font=("Consolas", 11, "bold")).pack(pady=(12, 4))\n        tk.Label(right, text="Sandboxed Actions Awaiting Approval", fg="#aaaaaa", bg="#0e141f", font=("Consolas", 8)).pack(pady=(0, 8))\n\n        self.guardrail_listbox = tk.Listbox(right, bg="#090d14", fg="#f1fa8c", font=("Consolas", 8), relief="flat", selectbackground="#28354d")\n        self.guardrail_listbox.pack(fill="both", expand=True, padx=10, pady=4)\n\n        gate_btns = tk.Frame(right, bg="#0e141f")\n        gate_btns.pack(fill="x", padx=10, pady=10)\n\n        tk.Button(\n            gate_btns, text="APPROVE & EXECUTE", command=lambda: self._handle_gate("APPROVED"),\n            bg="#50fa7b", fg="#070a0f", font=("Consolas", 9, "bold"), relief="flat", pady=6\n        ).pack(fill="x", pady=3)\n\n        tk.Button(\n            gate_btns, text="BLOCK & QUARANTINE", command=lambda: self._handle_gate("BLOCKED"),\n            bg="#ff5555", fg="#ffffff", font=("Consolas", 9, "bold"), relief="flat", pady=6\n        ).pack(fill="x", pady=3)\n\n    def _render_queue(self):\n        self.queue_box.delete("1.0", "end")\n        for idx, item in enumerate(self.task_queue, 1):\n            self.queue_box.insert("end", f"{idx}. [{item[\'division\']}] {item[\'name\']}\\n")\n\n    def _optimize_queue(self):\n        self.task_queue = self.engine.run_simulated_annealing(self.task_queue)\n        self._render_queue()\n        self.feed.insert("end", "[QUANTUM ANNEALER] Multi-division task queue re-ordered for minimum latency.\\n\\n")\n        self.feed.see("end")\n\n    def _launch_preset(self, div_code: str, prompt: str):\n        self.selected_division.set(div_code)\n        self.prompt_entry.delete(0, "end")\n        self.prompt_entry.insert(0, prompt)\n        self._dispatch_prompt()\n\n    def _dispatch_prompt(self):\n        prompt = self.prompt_entry.get().strip()\n        if not prompt:\n            return\n        self.prompt_entry.delete(0, "end")\n        division = self.selected_division.get()\n\n        for b_id, lbl in self.branch_labels.items():\n            lbl.config(text=f"{b_id}: RACING...", fg="#f1fa8c")\n\n        self.feed.insert("end", f"[DISPATCH -> {SWARM_DIVISIONS[division][\'title\']}] {prompt}\\n")\n        self.feed.see("end")\n\n        def worker():\n            result = self.engine.execute_quantum_race(division, prompt)\n            self.after(0, lambda: self._on_race_complete(result))\n\n        threading.Thread(target=worker, daemon=True).start()\n\n    def _on_race_complete(self, result: dict):\n        winner_id = result["branch"]\n        if "all_branches" in result:\n            for b in result["all_branches"]:\n                lbl = self.branch_labels.get(b["branch"])\n                if lbl:\n                    if b["branch"] == winner_id:\n                        lbl.config(text=f"{b[\'branch\']}: WINNER ({b[\'latency_ms\']}ms)", fg="#50fa7b")\n                    else:\n                        lbl.config(text=f"{b[\'branch\']}: CANCELLED ({b[\'latency_ms\']}ms)", fg="#6272a4")\n        else:\n            lbl = self.branch_labels.get(winner_id)\n            if lbl:\n                lbl.config(text=f"{winner_id}: RAM CACHE HIT (1ms)", fg="#00f0ff")\n\n        tag = "RAM-CACHE HIT" if result.get("cache_hit") else f"WINNER: {winner_id}"\n        self.feed.insert("end", f"[{tag} | {result[\'model\']} | {result[\'latency_ms\']}ms]\\n")\n        self.feed.insert("end", f"{result[\'output\']}\\n")\n        if "gate_id" in result:\n            self.feed.insert("end", f"[LAYER-05 SANDBOX] Action #{result[\'gate_id\']} queued for 1-click approval.\\n\\n")\n        else:\n            self.feed.insert("end", "\\n")\n        self.feed.see("end")\n        self._refresh_guardrails()\n        self._speak(f"Quantum swarm completed in {result[\'latency_ms\']} milliseconds.")\n\n    def _refresh_guardrails(self):\n        self.guardrail_listbox.delete(0, "end")\n        self.pending_rows = self.engine.get_pending_guardrails()\n        for row in self.pending_rows:\n            gate_id, swarm, action, payload_str, ts = row\n            data = json.loads(payload_str)\n            self.guardrail_listbox.insert("end", f"#{gate_id} | {data.get(\'division\')} | {data.get(\'prompt\')[:32]}...")\n\n    def _handle_gate(self, decision: str):\n        sel = self.guardrail_listbox.curselection()\n        if not sel:\n            return\n        row = self.pending_rows[sel[0]]\n        gate_id = row[0]\n        self.engine.resolve_guardrail(gate_id, decision)\n        self.feed.insert("end", f"[GUARDRAIL GATE #{gate_id}] Marked as {decision}.\\n\\n")\n        self.feed.see("end")\n        self._refresh_guardrails()\n\n\nif __name__ == "__main__":\n    app = QuantumSwarmDesktopApp()\n    app.mainloop()\n'

def install_and_launch():
    APP_DIR.mkdir(parents=True, exist_ok=True)
    app_file = APP_DIR / "quantum_swarm_studio.py"
    app_file.write_text(APP_SOURCE, encoding="utf-8")

    # Register in Layer 08 App Manifest
    manifest_file = OS_ROOT / "layer-08-division-apps" / "installed_apps.json"
    manifest_file.parent.mkdir(parents=True, exist_ok=True)
    manifest_file.write_text(
        '{"quantum_swarm_studio": {"name": "Quantum-Speed Worker Swarms Studio", "entry": "quantum-swarm-studio/quantum_swarm_studio.py", "layer": 8}}',
        encoding="utf-8"
    )

    # Create 1-click Desktop Launcher (No terminal window on Windows)
    if IS_WIN and DESKTOP_DIR.exists():
        bat_file = DESKTOP_DIR / "Jroc_Quantum_Swarm_Studio.bat"
        bat_file.write_text(f'@echo off\nstart "" pythonw "{app_file}"\n', encoding="utf-8")

    # Launch immediately
    if IS_WIN:
        subprocess.Popen(["pythonw", str(app_file)])
    else:
        subprocess.Popen([sys.executable, str(app_file)])

if __name__ == "__main__":
    install_and_launch()
